<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $errors!==[]?'Error: ':'' ?>Browse jobs · GigHub</title><link rel="stylesheet" href="assets/registration.css?v=4"><link rel="stylesheet" href="assets/jobs.css"><link rel="stylesheet" href="assets/job-browsing.css"></head>
<body>
<header class="site-header"><a class="brand" href="?route=/">GigHub</a><nav aria-label="Main navigation"><a href="?route=/login">Sign in</a><a href="?route=/register">Create an account</a></nav></header>
<main class="jobs-layout"><div class="jobs-heading"><p class="eyebrow">FIND YOUR NEXT PROJECT</p><h1>Browse jobs</h1><p>Explore open projects, compare advertised budgets and find work that fits your skills.</p></div>
<section class="card jobs-card browse-filters" aria-label="Search and filter jobs">
<?php if($errors!==[]): ?><div class="error-summary" role="alert"><h2>Check your search filters</h2><ul><?php foreach($errors as $field=>$message): ?><li><a href="#<?= $field==='page'?'browse-results':$escape($field) ?>"><?= $escape($message) ?></a></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="get" action="index.php"><input type="hidden" name="route" value="/jobs">
<label for="q">Search jobs</label><input type="search" id="q" name="q" value="<?= $escape($filters['q']) ?>" placeholder="Search titles and descriptions" aria-describedby="q-hint<?= isset($errors['q'])?' q-error':'' ?>"<?= isset($errors['q'])?' aria-invalid="true"':'' ?>>
<p class="hint" id="q-hint">Up to 100 characters. Search uses the text you enter, including punctuation.</p>
<?php if(isset($errors['q'])): ?><p class="field-error" id="q-error"><?= $escape($errors['q']) ?></p><?php endif; ?>
<div class="job-two-columns"><?php foreach(['min_budget'=>'Minimum budget (RM)','max_budget'=>'Maximum budget (RM)'] as $field=>$label): ?><div><label for="<?= $field ?>"><?= $label ?></label><input type="text" inputmode="decimal" id="<?= $field ?>" name="<?= $field ?>" value="<?= $escape($filters[$field]) ?>" aria-describedby="budget-hint<?= isset($errors[$field])?' '.$field.'-error':'' ?>"<?= isset($errors[$field])?' aria-invalid="true"':'' ?>><?php if(isset($errors[$field])): ?><p class="field-error" id="<?= $field ?>-error"><?= $escape($errors[$field]) ?></p><?php endif; ?></div><?php endforeach; ?></div>
<p class="hint" id="budget-hint">Optional inclusive budget range. Use up to two decimal places.</p>
<fieldset id="skills" tabindex="-1" aria-describedby="skills-hint<?= isset($errors['skills'])?' skills-error':'' ?>"<?= isset($errors['skills'])?' aria-invalid="true"':'' ?>><legend>Skills</legend><p class="hint" id="skills-hint">Choose up to 10. Jobs matching any selected skill are included.</p>
<?php if($skills===[]): ?><p>No catalogue skills are available. You can still search without a skill filter.</p><?php else: ?><div class="skill-grid"><?php foreach($skills as $skill): ?><label class="skill-option"><input type="checkbox" name="skills[]" value="<?= (int)$skill['id'] ?>"<?= in_array((int)$skill['id'],$filters['skills'],true)?' checked':'' ?>><span><?= $escape($skill['name']) ?></span></label><?php endforeach; ?></div><?php endif; ?>
<?php if(isset($errors['skills'])): ?><p class="field-error" id="skills-error"><?= $escape($errors['skills']) ?></p><?php endif; ?></fieldset>
<label for="sort">Sort by</label><select id="sort" name="sort"<?= isset($errors['sort'])?' aria-invalid="true" aria-describedby="sort-error"':'' ?>><?php foreach(['newest'=>'Newest first','budget_low'=>'Lowest budget','budget_high'=>'Highest budget'] as $value=>$label): ?><option value="<?= $value ?>"<?= $filters['sort']===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select>
<?php if(isset($errors['sort'])): ?><p class="field-error" id="sort-error"><?= $escape($errors['sort']) ?></p><?php endif; ?>
<div class="job-actions"><button type="submit">Apply filters</button><a href="?route=/jobs">Clear filters</a></div>
</form></section>
<section id="browse-results" aria-label="Job results" tabindex="-1">
<?php if($errors===[]): ?>
<?php if($jobs===[]): ?><div class="browse-empty"><h2>No jobs found</h2><p>Try changing your search or clearing the filters.</p></div><?php else: ?><ul class="job-list"><?php foreach($jobs as $job): ?><li class="card jobs-card"><h2><a href="?route=/jobs/show&amp;id=<?= (int)$job['id'] ?>"><?= $escape($job['title']) ?></a></h2><p><?= $escape(mb_substr($job['description'],0,180,'UTF-8').(mb_strlen($job['description'],'UTF-8')>180?'…':'')) ?></p><p>Advertised budget: RM<?= $escape(number_format((float)$job['budget'],2)) ?></p><p>Delivery deadline (Malaysia): <?= $escape($job['deadline']) ?></p><?php if($job['deadline']<$today): ?><p class="browse-warning">Delivery deadline has passed. This job remains open.</p><?php endif; ?><p class="hint">Created: <?= $escape(substr($job['created_at'],0,10)) ?> (UTC)</p><ul class="job-tags" aria-label="Required skills"><?php foreach($job['skills'] as $skill): ?><li><?= $escape($skill['name']) ?></li><?php endforeach; ?></ul></li><?php endforeach; ?></ul><?php endif; ?>
<?php if($jobs!==[]||$filters['page']>1): ?><nav class="job-pagination" aria-label="Job pages"><?php if($filters['page']>1): ?><a href="<?= $escape($pageUrl($filters['page']-1)) ?>">Previous</a><?php endif; ?><span>Page <?= $filters['page'] ?></span><?php if($hasNext): ?><a href="<?= $escape($pageUrl($filters['page']+1)) ?>">Next</a><?php endif; ?></nav><?php endif; ?>
<?php endif; ?></section></main></body></html>
